// In-Page Modal Dialogs (Prompt & Confirm) replacing native browser modal dialogs
function showModuCutPromptModal(title, labelText, defaultValue = "") {
  return new Promise((resolve) => {
    const existing = document.getElementById("moducut-generic-modal-backdrop");
    if (existing) existing.remove();
    const backdrop = document.createElement("div");
    backdrop.id = "moducut-generic-modal-backdrop";
    backdrop.className = "moducut-modal-backdrop";
    const escapeAttr = s => String(s || "").replace(/"/g, "&quot;");
    backdrop.innerHTML = `
      <div class="moducut-modal-dialog" role="dialog" aria-modal="true" style="width: 420px;">
        <div class="moducut-modal-header">
          <div class="moducut-modal-title">${escapeAttr(title)}</div>
          <button class="moducut-modal-close" id="moducut-prompt-close" type="button">✕</button>
        </div>
        <div class="moducut-modal-body">
          <div class="moducut-form-group">
            <label class="moducut-form-label" for="moducut-prompt-input">${escapeAttr(labelText)}</label>
            <input class="moducut-modal-input" id="moducut-prompt-input" type="text" value="${escapeAttr(defaultValue)}" />
          </div>
        </div>
        <div class="moducut-modal-footer">
          <button class="moducut-btn moducut-btn-secondary" id="moducut-prompt-cancel" type="button">Cancel</button>
          <button class="moducut-btn moducut-btn-primary" id="moducut-prompt-ok" type="button">Save</button>
        </div>
      </div>
    `;
    document.body.appendChild(backdrop);
    const inp = document.getElementById("moducut-prompt-input");
    const btnClose = document.getElementById("moducut-prompt-close");
    const btnCancel = document.getElementById("moducut-prompt-cancel");
    const btnOk = document.getElementById("moducut-prompt-ok");
    const cleanup = (val) => {
      backdrop.remove();
      resolve(val);
    };
    btnClose.addEventListener("click", () => cleanup(null));
    btnCancel.addEventListener("click", () => cleanup(null));
    btnOk.addEventListener("click", () => cleanup(inp ? inp.value : ""));
    backdrop.addEventListener("click", (e) => { if (e.target === backdrop) cleanup(null); });
    if (inp) {
      inp.focus();
      inp.select();
      inp.addEventListener("keydown", (e) => {
        if (e.key === "Enter") { e.preventDefault(); cleanup(inp.value); }
        else if (e.key === "Escape") { e.preventDefault(); cleanup(null); }
      });
    }
  });
}
window.showModuCutPromptModal = showModuCutPromptModal;

function showModuCutConfirmModal(title, messageText, confirmLabel = "Delete") {
  return new Promise((resolve) => {
    const existing = document.getElementById("moducut-generic-modal-backdrop");
    if (existing) existing.remove();
    const backdrop = document.createElement("div");
    backdrop.id = "moducut-generic-modal-backdrop";
    backdrop.className = "moducut-modal-backdrop";
    const escapeHtml = s => String(s || "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
    backdrop.innerHTML = `
      <div class="moducut-modal-dialog" role="dialog" aria-modal="true" style="width: 400px;">
        <div class="moducut-modal-header">
          <div class="moducut-modal-title">${escapeHtml(title)}</div>
          <button class="moducut-modal-close" id="moducut-confirm-close" type="button">✕</button>
        </div>
        <div class="moducut-modal-body">
          <p style="margin: 0; font-size: 13px; color: #334155; line-height: 1.5;">${escapeHtml(messageText)}</p>
        </div>
        <div class="moducut-modal-footer">
          <button class="moducut-btn moducut-btn-secondary" id="moducut-confirm-cancel" type="button">Cancel</button>
          <button class="moducut-btn moducut-btn-danger" id="moducut-confirm-ok" type="button">${escapeHtml(confirmLabel)}</button>
        </div>
      </div>
    `;
    document.body.appendChild(backdrop);
    const btnClose = document.getElementById("moducut-confirm-close");
    const btnCancel = document.getElementById("moducut-confirm-cancel");
    const btnOk = document.getElementById("moducut-confirm-ok");
    const cleanup = (val) => {
      backdrop.remove();
      resolve(val);
    };
    btnClose.addEventListener("click", () => cleanup(false));
    btnCancel.addEventListener("click", () => cleanup(false));
    btnOk.addEventListener("click", () => cleanup(true));
    backdrop.addEventListener("click", (e) => { if (e.target === backdrop) cleanup(false); });
  });
}
window.showModuCutConfirmModal = showModuCutConfirmModal;

// Path Length & Laser Time Estimator Modal (Speed by Color)
function formatLaserTimeHHMMSS(totalSeconds) {
  if (!isFinite(totalSeconds) || totalSeconds <= 0) return "00:00:00";
  const rounded = Math.round(totalSeconds);
  const hrs = Math.floor(rounded / 3600);
  const mins = Math.floor((rounded % 3600) / 60);
  const secs = rounded % 60;
  return [hrs, mins, secs].map(v => String(v).padStart(2, "0")).join(":");
}

function collectSelectedPathStats() {
  const projectUnits = (nz && nz.project && nz.project.settings && nz.project.settings.units) || "in";
  const projectToMm = (typeof ec === "function")
    ? ec(projectUnits, "mm")
    : (projectUnits === "mm" ? 1 : projectUnits === "cm" ? 10 : 25.4);
  const mmToProject = 1 / projectToMm;

  const rawNodes = (nz && nz.project && nz.project.selection && nz.project.selection.allNodes)
    ? nz.project.selection.allNodes().sortInDocumentOrder().toNodes()
    : [];

  const selectedSet = new Set(rawNodes);
  const topNodes = rawNodes.filter(node => {
    let p = node && node.parent;
    while (p) {
      if (selectedSet.has(p)) return false;
      p = p.parent;
    }
    return true;
  });

  let totalPathCount = 0;
  let totalLengthMm = 0;
  const byColorMap = new Map();

  function extractColorInfo(styleObj) {
    if (!styleObj) return null;
    if (styleObj.color) {
      if (typeof styleObj.color.a === "number" && styleObj.color.a <= 0) return null;
      const hex = (typeof styleObj.color.toCSSHexString === "function")
        ? styleObj.color.toCSSHexString().toUpperCase()
        : "#000000";
      return { hex, label: hex };
    }
    return { hex: "#888888", label: "Gradient / Image" };
  }

  function addColorBucket(colorHex, colorLabel, lenMm) {
    const key = colorLabel;
    let entry = byColorMap.get(key);
    if (!entry) {
      entry = { colorHex, colorLabel, count: 0, lengthMm: 0 };
      byColorMap.set(key, entry);
    }
    entry.count += 1;
    entry.lengthMm += lenMm;
  }

  function walkGeometry(geom, inheritedStroke, inheritedFill) {
    if (!geom) return;
    const effStroke = geom.stroke || inheritedStroke;
    const effFill = geom.fill || inheritedFill;

    if (Array.isArray(geom.items)) {
      for (const child of geom.items) {
        walkGeometry(child, effStroke, effFill);
      }
      return;
    }
    if (Array.isArray(geom.paths)) {
      for (const childPath of geom.paths) {
        walkGeometry(childPath, effStroke, effFill);
      }
      return;
    }
    if (typeof geom.length === "function" && Array.isArray(geom.anchors)) {
      const lenProj = geom.length();
      if (!isFinite(lenProj) || lenProj <= 0) return;
      const lenMm = lenProj * projectToMm;
      totalPathCount += 1;
      totalLengthMm += lenMm;

      const colorInfo = extractColorInfo(effStroke) || extractColorInfo(effFill) || { hex: "#CCCCCC", label: "No Color" };
      addColorBucket(colorInfo.hex, colorInfo.label, lenMm);
    }
  }

  for (const node of topNodes) {
    try {
      const trace = nz.traceForNode(node);
      if (trace && trace.isSuccess() && trace.result) {
        walkGeometry(trace.result, null, null);
      }
    } catch (err) {
      console.warn("Path length trace error:", err);
    }
  }

  const byColor = Array.from(byColorMap.values()).sort((a, b) => b.lengthMm - a.lengthMm);

  return {
    totalPathCount,
    totalLengthMm,
    projectUnits,
    mmToProject,
    byColor
  };
}

function openPathLengthEstimatorModal() {
  const stats = collectSelectedPathStats();
  const existing = document.getElementById("moducut-path-length-modal-backdrop");
  if (existing) existing.remove();

  let defaultSpeed = 20;
  let savedSpeedByColor = {};
  try {
    const d = parseFloat(localStorage.getItem("moducut_laser_default_speed_mm_s"));
    if (isFinite(d) && d > 0) defaultSpeed = d;
    const rawMap = localStorage.getItem("moducut_laser_speed_by_color");
    if (rawMap) {
      const parsed = JSON.parse(rawMap);
      if (parsed && typeof parsed === "object") savedSpeedByColor = parsed;
    }
  } catch (_) {}

  const showProjectUnit = stats.projectUnits && stats.projectUnits !== "mm";
  const fmtMm = (mm) => mm.toFixed(2) + " mm";
  const fmtProjUnit = (mm) => (mm * stats.mmToProject).toFixed(2) + " " + stats.projectUnits;
  const fmtLenDual = (mm) => showProjectUnit ? `${fmtMm(mm)} (${fmtProjUnit(mm)})` : fmtMm(mm);

  const appFont = '-apple-system, BlinkMacSystemFont, "Segoe UI", Helvetica, Arial, sans-serif, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol"';
  const monoFont = 'SFMono-Regular, Consolas, "Liberation Mono", Menlo, Courier, monospace';

  const backdrop = document.createElement("div");
  backdrop.id = "moducut-path-length-modal-backdrop";
  backdrop.style.cssText = "position:fixed;inset:0;background:rgba(0,0,0,0.6);z-index:999999;display:flex;align-items:center;justify-content:center;font-family:" + appFont + ";font-size:14px;line-height:20px;color:#000000d9;";

  const rowHtml = stats.byColor.map((row, idx) => {
    const saved = parseFloat(savedSpeedByColor[row.colorLabel]);
    const rowSpeed = (isFinite(saved) && saved > 0) ? saved : defaultSpeed;
    return `
      <tr style="border-bottom:1px solid hsl(0,0%,91%);background:#ffffff;">
        <td style="padding:8px 12px;vertical-align:middle;">
          <span style="display:inline-flex;align-items:center;gap:8px;">
            <span style="width:14px;height:14px;border-radius:3px;background:${row.colorHex};border:1px solid rgba(0,0,0,0.22);display:inline-block;flex-shrink:0;"></span>
            <span style="font-family:${monoFont};font-size:12.5px;color:#000000d9;">${row.colorLabel}</span>
          </span>
        </td>
        <td style="padding:8px 12px;text-align:right;vertical-align:middle;font-variant-numeric:tabular-nums;color:rgba(0,0,0,0.65);">${row.count}</td>
        <td style="padding:8px 12px;text-align:right;vertical-align:middle;font-variant-numeric:tabular-nums;color:#000000d9;">${fmtLenDual(row.lengthMm)}</td>
        <td style="padding:8px 12px;text-align:right;vertical-align:middle;">
          <input type="number" class="mc-pl-color-speed" data-idx="${idx}" min="0.1" step="1" value="${rowSpeed}"
            style="width:84px;padding:4px 7px;border:1px solid rgba(0,0,0,0.2);border-radius:4px;font-size:13px;font-family:${appFont};color:#000000d9;background:#ffffff;text-align:right;outline:none;box-sizing:border-box;" />
        </td>
        <td id="mc-pl-row-time-${idx}" style="padding:8px 12px;text-align:right;vertical-align:middle;font-family:${monoFont};font-size:13px;font-weight:600;color:#000000d9;">00:00:00</td>
      </tr>
    `;
  }).join("");

  backdrop.innerHTML = `
    <div role="dialog" aria-modal="true" style="width:660px;max-width:94vw;background:#ffffff;border-radius:4px;box-shadow:0 2px 4px #00000026,0 4px 16px #0000001a;overflow:hidden;display:flex;flex-direction:column;font-family:${appFont};color:#000000d9;">
      <div style="padding:12px 16px;background:#f5f5f5;border-bottom:1px solid hsl(0,0%,91%);display:flex;align-items:center;justify-content:space-between;">
        <div style="display:flex;align-items:center;gap:10px;">
          <span style="font-size:14px;font-weight:600;color:#000000d9;">Path Length &amp; Time Estimate</span>
          <span style="font-size:12px;color:rgba(0,0,0,0.6);background:#e8e8e8;padding:1px 8px;border-radius:10px;">${stats.totalPathCount} path${stats.totalPathCount === 1 ? "" : "s"} selected</span>
        </div>
        <button id="mc-pl-close" title="Close" style="background:transparent;border:none;font-size:16px;line-height:1;padding:4px 6px;border-radius:4px;color:rgba(0,0,0,0.55);cursor:pointer;">✕</button>
      </div>

      <div style="padding:16px;display:flex;flex-direction:column;gap:12px;max-height:74vh;overflow-y:auto;background:#ffffff;">
        <div style="display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:10px;padding:10px 12px;background:#fafafa;border:1px solid hsl(0,0%,91%);border-radius:4px;">
          <div style="font-size:13px;color:rgba(0,0,0,0.72);">Set speed (mm/sec) per colour below, or apply one speed to all colours:</div>
          <div style="display:flex;align-items:center;gap:6px;">
            <input type="number" id="mc-pl-global-speed" min="0.1" step="1" value="${defaultSpeed}"
              style="width:78px;padding:4px 7px;border:1px solid rgba(0,0,0,0.2);border-radius:4px;font-size:13px;font-family:${appFont};color:#000000d9;background:#ffffff;text-align:right;outline:none;box-sizing:border-box;" />
            <span style="font-size:12px;color:rgba(0,0,0,0.55);">mm/sec</span>
            <button id="mc-pl-apply-all" style="padding:4px 10px;border:1px solid rgba(0,0,0,0.2);border-radius:4px;background:#f5f5f5;color:#000000d9;font-size:12.5px;font-family:${appFont};font-weight:500;cursor:pointer;">Apply to All</button>
          </div>
        </div>

        ${stats.byColor.length === 0 ? `
          <div style="padding:20px;text-align:center;color:rgba(0,0,0,0.55);background:#fafafa;border:1px solid hsl(0,0%,91%);border-radius:4px;font-size:13px;">
            No measurable vector paths found in the current selection.
          </div>
        ` : `
          <div style="border:1px solid hsl(0,0%,91%);border-radius:4px;overflow:hidden;">
            <table style="width:100%;border-collapse:collapse;font-size:13px;font-family:${appFont};">
              <thead>
                <tr style="background:#f5f5f5;border-bottom:1px solid hsl(0,0%,91%);color:rgba(0,0,0,0.65);text-align:left;">
                  <th style="padding:8px 12px;font-weight:600;">Colour</th>
                  <th style="padding:8px 12px;font-weight:600;text-align:right;">Paths</th>
                  <th style="padding:8px 12px;font-weight:600;text-align:right;">Path Length</th>
                  <th style="padding:8px 12px;font-weight:600;text-align:right;">Speed (mm/sec)</th>
                  <th style="padding:8px 12px;font-weight:600;text-align:right;">Time (hh:mm:ss)</th>
                </tr>
              </thead>
              <tbody>
                ${rowHtml}
              </tbody>
              <tfoot>
                <tr style="background:#f5f5f5;border-top:1px solid rgba(0,0,0,0.18);font-weight:600;color:#000000d9;">
                  <td style="padding:10px 12px;">Total</td>
                  <td style="padding:10px 12px;text-align:right;font-variant-numeric:tabular-nums;">${stats.totalPathCount}</td>
                  <td style="padding:10px 12px;text-align:right;font-variant-numeric:tabular-nums;">${fmtLenDual(stats.totalLengthMm)}</td>
                  <td style="padding:10px 12px;text-align:right;color:rgba(0,0,0,0.45);">—</td>
                  <td id="mc-pl-total-time-foot" style="padding:10px 12px;text-align:right;font-family:${monoFont};font-size:13.5px;font-weight:700;color:#000000d9;">00:00:00</td>
                </tr>
              </tfoot>
            </table>
          </div>
        `}
      </div>

      <div style="padding:10px 16px;background:#f5f5f5;border-top:1px solid hsl(0,0%,91%);display:flex;align-items:center;justify-content:space-between;">
        <button id="mc-pl-copy" style="padding:6px 12px;border:1px solid rgba(0,0,0,0.2);border-radius:4px;background:#ffffff;color:#000000d9;font-size:13px;font-family:${appFont};font-weight:500;cursor:pointer;">Copy Summary</button>
        <button id="mc-pl-done" style="padding:6px 16px;border:1px solid #2563eb;border-radius:4px;background:#2563eb;color:#ffffff;font-size:13px;font-family:${appFont};font-weight:500;cursor:pointer;">Close</button>
      </div>
    </div>
  `;

  document.body.appendChild(backdrop);

  const globalSpeedInput = backdrop.querySelector("#mc-pl-global-speed");
  const applyAllBtn = backdrop.querySelector("#mc-pl-apply-all");
  const totalFootEl = backdrop.querySelector("#mc-pl-total-time-foot");
  const copyBtn = backdrop.querySelector("#mc-pl-copy");
  const rowSpeedInputs = Array.from(backdrop.querySelectorAll(".mc-pl-color-speed"));

  function updateTimes() {
    let totalSec = 0;
    stats.byColor.forEach((row, idx) => {
      const inp = rowSpeedInputs[idx];
      const spd = inp ? parseFloat(inp.value) : 0;
      const validSpd = (isFinite(spd) && spd > 0) ? spd : 0;
      if (validSpd > 0) {
        savedSpeedByColor[row.colorLabel] = validSpd;
      }
      const sec = validSpd > 0 ? (row.lengthMm / validSpd) : 0;
      totalSec += sec;
      const cell = backdrop.querySelector("#mc-pl-row-time-" + idx);
      if (cell) cell.textContent = formatLaserTimeHHMMSS(sec);
    });
    if (totalFootEl) totalFootEl.textContent = formatLaserTimeHHMMSS(totalSec);
    try {
      localStorage.setItem("moducut_laser_speed_by_color", JSON.stringify(savedSpeedByColor));
    } catch (_) {}
  }

  rowSpeedInputs.forEach(inp => {
    inp.addEventListener("input", updateTimes);
  });

  if (applyAllBtn) {
    applyAllBtn.addEventListener("click", () => {
      const val = parseFloat(globalSpeedInput.value);
      if (!isFinite(val) || val <= 0) return;
      try {
        localStorage.setItem("moducut_laser_default_speed_mm_s", String(val));
      } catch (_) {}
      rowSpeedInputs.forEach(inp => { inp.value = String(val); });
      updateTimes();
    });
  }

  if (globalSpeedInput) {
    globalSpeedInput.addEventListener("keydown", (ev) => {
      if (ev.key === "Enter" && applyAllBtn) {
        ev.preventDefault();
        applyAllBtn.click();
      }
    });
  }

  if (copyBtn) {
    copyBtn.addEventListener("click", () => {
      let totalSec = 0;
      const lines = [
        `Path Length & Time Estimate (${stats.totalPathCount} paths selected)`,
        ""
      ];
      stats.byColor.forEach((row, idx) => {
        const inp = rowSpeedInputs[idx];
        const spd = inp ? parseFloat(inp.value) : 0;
        const validSpd = (isFinite(spd) && spd > 0) ? spd : 0;
        const sec = validSpd > 0 ? (row.lengthMm / validSpd) : 0;
        totalSec += sec;
        lines.push(`${row.colorLabel} | ${row.count} paths | ${fmtLenDual(row.lengthMm)} | ${validSpd} mm/sec | ${formatLaserTimeHHMMSS(sec)}`);
      });
      lines.push(`Total | ${stats.totalPathCount} paths | ${fmtLenDual(stats.totalLengthMm)} | ${formatLaserTimeHHMMSS(totalSec)}`);
      const text = lines.join("\n");
      if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(text).then(() => {
          copyBtn.textContent = "Copied";
          setTimeout(() => { copyBtn.textContent = "Copy Summary"; }, 1500);
        }).catch(() => {});
      }
    });
  }

  const close = () => {
    document.removeEventListener("keydown", onKey);
    backdrop.remove();
  };
  const onKey = (ev) => {
    if (ev.key === "Escape") close();
  };
  document.addEventListener("keydown", onKey);
  backdrop.querySelector("#mc-pl-close").onclick = close;
  backdrop.querySelector("#mc-pl-done").onclick = close;
  backdrop.onclick = (ev) => { if (ev.target === backdrop) close(); };

  updateTimes();
  if (rowSpeedInputs.length > 0) {
    setTimeout(() => { rowSpeedInputs[0].focus(); rowSpeedInputs[0].select(); }, 30);
  }
}
window.openPathLengthEstimatorModal = openPathLengthEstimatorModal;

